def compare_particles(particles: dict, ex_particles: dict) -> None:
    for k in range(len(particles.keys())):
        res_particles = particles[k]
        exp_particle = ex_particles[k]
        res_particles["neighbor_ids"].sort()
        exp_particle["neighbor_ids"].sort()
        for i in range(len(res_particles["position"])):
            is_close = math.isclose(res_particles["position"][i], exp_particle["position"][i], abs_tol=5)
            if not is_close:
                print(i, res_particles["position"][i], exp_particle["position"][i])
                assert is_close
        assert res_particles["type_name"] == exp_particle["type_name"]

def compare_topologies(topologies: dict, ex_topologies: dict) -> None:
    ex_pids = {str(sorted(ex_topologies[k]['particle_ids'])): ex_topologies[k] for k in ex_topologies.keys()}
    t_pids = {str(sorted(topologies[k]['particle_ids'])): topologies[k] for k in topologies.keys()}
    for k in ex_pids.keys():
        t_pids[k]["particle_ids"].sort()
        ex_pids[k]["particle_ids"].sort()

        assert t_pids[k]["particle_ids"] == ex_pids[k]["particle_ids"]
        assert t_pids[k]["type_name"] == ex_pids[k]["type_name"]


